(3981958, 567891, 67237, '<td valign="top">good light and execution</td>', 'good light and execution', '2007-08-08 19:20:42.000000', NULL, 1),
(3981968, 567728, 67237, '<td valign="top">it looks really noisy.<br/>try to use any noise reduction software such as NeatImage Ninja or other. Avoid shooting in high ISO unless it''s necessary.</td>', 'it looks really noisy.try to use any noise reduction software such as NeatImage Ninja or other. Avoid shooting in high ISO unless it''s necessary.', '2007-08-08 19:25:19.000000', NULL, 1),
(3981981, 567979, 67237, '<td valign="top">This is hillarious. A bit off focus.<br/>I would have liked a tighter crop on the right side and a less sloped "horizon".</td>', 'This is hillarious. A bit off focus.I would have liked a tighter crop on the right side and a less sloped "horizon".', '2007-08-08 19:32:54.000000', NULL, 1),
(3981987, 566982, 67237, '<td valign="top">too bad the white handle kind of merges with the white flower resulting in such a distracting element. I think, a tighter crop on the left side an a bit more room on right and top could have helped. <br/> <br/>Other that that, a nice and well executed photo.</td>', 'too bad the white handle kind of merges with the white flower resulting in such a distracting element. I think, a tighter crop on the left side an a bit more room on right and top could have helped.  Other that that, a nice and well executed photo.', '2007-08-08 19:36:23.000000', NULL, 1),
(3981989, 567951, 67237, '<td valign="top">yeah, but you dont want him to take pictures like this :-) just kidding!!</td>', 'yeah, but you dont want him to take pictures like this :-) just kidding!!', '2007-08-08 19:37:31.000000', NULL, 1),
(3982000, 567312, 67237, '<td valign="top">nice shot. b&amp;w works here.<br/>story is too much "not belieavable" though..a human bare footed kid in the middle of the highway?..IMO it could have worked better a diagonal composition having him walk on the side.</td>', 'nice shot. b&w works here.story is too much "not belieavable" though..a human bare footed kid in the middle of the highway?..IMO it could have worked better a diagonal composition having him walk on the side.', '2007-08-08 19:43:28.000000', NULL, 1),
(3982008, 567952, 67237, '<td valign="top">well executed photo. it looks a bit snappish though.</td>', 'well executed photo. it looks a bit snappish though.', '2007-08-08 19:45:37.000000', NULL, 1),
