INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3996142, 564845, 81642, '<td valign="top">Very very good.</td>', 'Very very good.', '2007-08-14 04:40:09.000000', NULL, 1),
(3996150, 567927, 49109, '<td valign="top">cute shot, very well done</td>', 'cute shot, very well done', '2007-08-14 04:49:42.000000', NULL, 1),
(3996151, 567114, 49109, '<td valign="top">main subject is not the bear (at least we should see his face, reversing him had also hidden the manufacturers tag), but it''s a very good portrait of your daughter. very good composition, good lighting, though a bit too dark at left where the chair merges with the background. perfectly matching props (i.e. her dress and the chair), go very well with her red hair - had chosen an equivalent color for the thin border. Note: it''s better to add the border after resizing, otherwise it will look blurred and have rounded corners (as shown here). <br/>Hopefully this will at least make top10.</td>', 'main subject is not the bear (at least we should see his face, reversing him had also hidden the manufacturers tag), but it''s a very good portrait of your daughter. very good composition, good lighting, though a bit too dark at left where the chair merges with the background. perfectly matching props (i.e. her dress and the chair), go very well with her red hair - had chosen an equivalent color for the thin border. Note: it''s better to add the border after resizing, otherwise it will look blurred and have rounded corners (as shown here). Hopefully this will at least make top10.', '2007-08-14 04:49:44.000000', NULL, 1),
(3996152, 566996, 49109, '<td valign="top">great detail and textures.</td>', 'great detail and textures.', '2007-08-14 04:49:50.000000', NULL, 1),
(3996153, 567878, 49109, '<td valign="top">good boy! the most simple ideas always work best! good lighting and comp.</td>', 'good boy! the most simple ideas always work best! good lighting and comp.', '2007-08-14 04:49:54.000000', NULL, 1),
