(3996352, 567733, 82534, '<td valign="top">Great use of light.  Looks very real as if a fog were lifting or smoke were clearing.  Really like it.</td>', 'Great use of light.  Looks very real as if a fog were lifting or smoke were clearing.  Really like it.', '2007-08-14 09:19:46.000000', NULL, 1),
(3996353, 567203, 82534, '<td valign="top">Very unique.  Can see the grain in the wood so clearly and the depth of field is spot on.  Very nice capture.</td>', 'Very unique.  Can see the grain in the wood so clearly and the depth of field is spot on.  Very nice capture.', '2007-08-14 09:19:54.000000', NULL, 1),
(3996354, 567688, 82534, '<td valign="top">The lighting is quite nice -- especially since it lights up the eyes.  Great idea!</td>', 'The lighting is quite nice -- especially since it lights up the eyes.  Great idea!', '2007-08-14 09:20:03.000000', NULL, 1),
(3996355, 566547, 82534, '<td valign="top">Great macro work!  Even with a small model, you''ve managed to make it look life size and captured all the proper highlights.  Very nice shot.</td>', 'Great macro work!  Even with a small model, you''ve managed to make it look life size and captured all the proper highlights.  Very nice shot.', '2007-08-14 09:20:13.000000', NULL, 1),
(3996356, 567860, 82534, '<td valign="top">That''s just too funny!  Very neat twist to this challenge.</td>', 'That''s just too funny!  Very neat twist to this challenge.', '2007-08-14 09:20:18.000000', NULL, 1),
(3996357, 567846, 82534, '<td valign="top">I love how you have his head fading into the white background while keeping the slinky sharp.  Well done.</td>', 'I love how you have his head fading into the white background while keeping the slinky sharp.  Well done.', '2007-08-14 09:20:24.000000', NULL, 1),
