(3996367, 566028, 82534, '<td valign="top">The gaps under the track are a bit distracting to me, but I still really like the image.</td>', 'The gaps under the track are a bit distracting to me, but I still really like the image.', '2007-08-14 09:21:47.000000', NULL, 1),
(3996368, 567006, 82534, '<td valign="top">Beautiful backdrop!  The bright red of the ATV stands in sharp contrast to the muted tones of the sky.</td>', 'Beautiful backdrop!  The bright red of the ATV stands in sharp contrast to the muted tones of the sky.', '2007-08-14 09:21:55.000000', NULL, 1),
(3996371, 567395, 82534, '<td valign="top">I really like the lighting here.  For some reason, it draws me into the image and the left half has almost an illusion effect going on with the slinky.  Really like this.</td>', 'I really like the lighting here.  For some reason, it draws me into the image and the left half has almost an illusion effect going on with the slinky.  Really like this.', '2007-08-14 09:22:35.000000', NULL, 1),
