(3996373, 566986, 82534, '<td valign="top">Great shadows and I love the colors at the top of each block.  Very nicely done!</td>', 'Great shadows and I love the colors at the top of each block.  Very nicely done!', '2007-08-14 09:22:54.000000', NULL, 1),
(3996374, 567941, 82534, '<td valign="top">Really nice reflection in the foreground.</td>', 'Really nice reflection in the foreground.', '2007-08-14 09:22:58.000000', NULL, 1),
