(4073433, 567915, 55330, '<td valign="top">very cute, I love the little badge</td>', 'very cute, I love the little badge', '2007-09-08 22:41:17.000000', NULL, 0),
(4079311, 567925, 40718, '<td valign="top">Technicals: I highly suggest you learn to use channel mixer for converting to B&amp;W (if you use photoshop).  You have a lot more control.  To my eye the picture looks just a tad too sharp in places.  The subject, unfortunately, is also lost in the BG.  I know you were somewhat going for this, but you have to do it so the viewer understands the trike has been abandoned, but it actually stands out on a technical POV.  Selective desat might be one application.<br/> <br/>The feel: As mentioned in technicals, I think a limiting factor is the trike is too lost in the composition.  Some of the textures, like the grass, are too harsh as well.  This is a shot using some gaussian blur might even work better.<br/> <br/>The game: Maybe even go for sepia?  That might have added to the nostalgic feel and gotten you another tenth.</td>', 'Technicals: I highly suggest you learn to use channel mixer for converting to B&W (if you use photoshop).  You have a lot more control.  To my eye the picture looks just a tad too sharp in places.  The subject, unfortunately, is also lost in the BG.  I know you were somewhat going for this, but you have to do it so the viewer understands the trike has been abandoned, but it actually stands out on a technical POV.  Selective desat might be one application. The feel: As mentioned in technicals, I think a limiting factor is the trike is too lost in the composition.  Some of the textures, like the grass, are too harsh as well.  This is a shot using some gaussian blur might even work better. The game: Maybe even go for sepia?  That might have added to the nostalgic feel and gotten you another tenth.', '2007-09-10 21:36:33.000000', NULL, 0),
(4080616, 566597, 80904, '<td valign="top">Alright I am going to return the favor since you have been kind enough to give me some of your time and input on my shot. I love your honesty.<br/> <br/>Anyway, here I go:<br/> <br/>I gave this shot a 5.0, why? <br/>Well the shot isn''t bad, but it isnt great either. It doesnt say much, it is just there (trust me I have alot of those shots too). This would have been a better candidate for fill the frame than toys. To be honest, anyone with a camera could have taken this shot. It looked to me that you relied more on the subject itself (that being the toy) rather than technique and creativity on your behalf (which you do have alot of creativity, just not in this shot). I do like the sharpness and the fact that the face is in focus and the rest is a bit out of focus and how green takes over. However those qualities were not strong enough to carry the photo. I feel that the lack of creativity in this shot was problably it''s result of the score given. Once again good shot, not great. Looked more to me that you relied more on the cuteness of the subject rather to emphasize on your creativity and camera techniques. That is why I gave it a 5.</td>', 'Alright I am going to return the favor since you have been kind enough to give me some of your time and input on my shot. I love your honesty. Anyway, here I go: I gave this shot a 5.0, why? Well the shot isn''t bad, but it isnt great either. It doesnt say much, it is just there (trust me I have alot of those shots too). This would have been a better candidate for fill the frame than toys. To be honest, anyone with a camera could have taken this shot. It looked to me that you relied more on the subject itself (that being the toy) rather than technique and creativity on your behalf (which you do have alot of creativity, just not in this shot). I do like the sharpness and the fact that the face is in focus and the rest is a bit out of focus and how green takes over. However those qualities were not strong enough to carry the photo. I feel that the lack of creativity in this shot was problably it''s result of the score given. Once again good shot, not great. Looked more to me that you relied more on the cuteness of the subject rather to emphasize on your creativity and camera techniques. That is why I gave it a 5.', '2007-09-11 09:57:18.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4082057, 566597, 40718, '<td valign="top">Aww, do I bust you for being 0.0084 over 5.5?  Naw, I''ll let you slide.<br/> <br/>Technicals: well lit.  The centered composition isn''t bad here.  Focus is on.<br/> <br/>The feel: The toy does bring a smile to my face.  It''s cute and the colors are nice against the black background.<br/> <br/>The game: It''s a toy and nothing else.  yes, I know the challenge was "toys", but we don''t have too much to work with after the cute look and the nice green color.  I think you squeezed about as high a score as possible for your subject.  Using him in some context may have done you better.</td>', 'Aww, do I bust you for being 0.0084 over 5.5?  Naw, I''ll let you slide. Technicals: well lit.  The centered composition isn''t bad here.  Focus is on. The feel: The toy does bring a smile to my face.  It''s cute and the colors are nice against the black background. The game: It''s a toy and nothing else.  yes, I know the challenge was "toys", but we don''t have too much to work with after the cute look and the nice green color.  I think you squeezed about as high a score as possible for your subject.  Using him in some context may have done you better.', '2007-09-11 19:53:23.000000', NULL, 0),
(4112958, 567102, 73433, '<td valign="top">omg! "i don''t care who you are, that''s funny right right thar"-Larry the Cable Guy</td>', 'omg! "i don''t care who you are, that''s funny right right thar"-Larry the Cable Guy', '2007-09-24 17:41:00.000000', NULL, 0),
(4114996, 567295, 56999, '<td valign="top">I Like the this image. The Coloration is bright and "neon" against the grey background. The ball looks to be in motion and I would have to agree a little curves adjustment or brightness and contrast would go a long way. Good Job.</td>', 'I Like the this image. The Coloration is bright and "neon" against the grey background. The ball looks to be in motion and I would have to agree a little curves adjustment or brightness and contrast would go a long way. Good Job.', '2007-09-25 17:17:12.000000', NULL, 0),
